//============================================================
// ============================================================
// argmax_wrapper.v
// ------------------------------------------------------------
// Sequentially reads 10 INT16 logits from the feature buffer
// (one per cycle, sync read with 1-cycle latency), latches them
// into 10 parallel registers, and then invokes the combinational
// argmax10 to find the winning class.
//
// Why needed:
//   argmax10 is purely combinational and expects all 10 logits
//   simultaneously. The feature buffer has one read port, so we
//   need a small FSM to gather the 10 values.
//
// Data contract:
//   Before start:  the preceding fc3 step has written 10 logits
//                  to the feature buffer, at addresses 0..9 (after
//                  the ping-pong swap that followed fc3).
//   After done:    class_out holds the predicted class index (0..9).
//
// fc3 outputs 16-bit values (INT16 logits). The feature buffer is
// 8-bit wide, so fc3 actually writes 2 consecutive bytes per logit
// — but wait, that's a problem that needs resolving at the top
// level. For now, this wrapper assumes a dedicated 16-bit-wide
// logit buffer is provided externally via logit_fmap_in.
//
// The simplest top-level solution (documented in lenet5_top.v):
// have fc3 write its 10 logits into a small dedicated register
// file (logit_buf[10]) rather than the 8-bit feature buffer.
// This wrapper reads from that register file.
// ============================================================

`timescale 1ns / 1ps

module argmax_wrapper #(
    parameter integer LOGIT_W = 16    // fc3 logits are INT16
)(
    input  wire                         clk,
    input  wire                         rst_n,
    input  wire                         start,

    // Address we want to read (0..9), one logit per cycle
    output reg  [3:0]                   logit_addr,
    // Logit value for the currently-addressed index
    // (combinational from a small register file; no sync read delay)
    input  wire signed [LOGIT_W-1:0]    logit_in,

    // Result
    output reg  [3:0]                   class_out,
    output reg                          done
);

    // =========================================================
    // FSM
    // =========================================================
    localparam S_IDLE    = 3'd0;
    localparam S_READ    = 3'd1;     // step through addresses 0..9, capture
    localparam S_COMPUTE = 3'd2;     // argmax10 result is ready (combinational)
    localparam S_DONE    = 3'd3;

    reg [2:0] state, next_state;
    reg [3:0] read_cnt;

    wire last_logit = (read_cnt == 4'd9);

    // =========================================================
    // 10 parallel registers to hold the logits
    // =========================================================
    reg signed [LOGIT_W-1:0] v0, v1, v2, v3, v4, v5, v6, v7, v8, v9;

    // =========================================================
    // Instantiate argmax10 (combinational)
    // argmax10 expects DATA_WIDTH-wide signed inputs. Default is 16.
    // =========================================================
    wire [3:0] argmax_idx;

    argmax10 #(.WIDTH(LOGIT_W)) u_argmax (
        .in0(v0), .in1(v1), .in2(v2), .in3(v3), .in4(v4),
        .in5(v5), .in6(v6), .in7(v7), .in8(v8), .in9(v9),
        .idx_out(argmax_idx)
    );

    // =========================================================
    // Next-state logic
    // =========================================================
    always @(*) begin
        next_state = state;
        case (state)
            S_IDLE:    if (start)       next_state = S_READ;
            S_READ:    if (last_logit)  next_state = S_COMPUTE;
            S_COMPUTE:                  next_state = S_DONE;
            S_DONE:                     next_state = S_IDLE;
            default:                    next_state = S_IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= S_IDLE;
        else        state <= next_state;
    end

    // =========================================================
    // Address counter
    // Since logit_in is combinational (not sync-read), we can
    // capture each value in the same cycle we issue its address.
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            read_cnt <= 0;
        end else if (state == S_IDLE && start) begin
            read_cnt <= 0;
        end else if (state == S_READ) begin
            if (!last_logit) read_cnt <= read_cnt + 1;
        end
    end

    always @(*) logit_addr = read_cnt;

    // =========================================================
    // Capture logits into v0..v9 as we iterate
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            v0 <= 0; v1 <= 0; v2 <= 0; v3 <= 0; v4 <= 0;
            v5 <= 0; v6 <= 0; v7 <= 0; v8 <= 0; v9 <= 0;
        end else if (state == S_READ) begin
            case (read_cnt)
                4'd0: v0 <= logit_in;
                4'd1: v1 <= logit_in;
                4'd2: v2 <= logit_in;
                4'd3: v3 <= logit_in;
                4'd4: v4 <= logit_in;
                4'd5: v5 <= logit_in;
                4'd6: v6 <= logit_in;
                4'd7: v7 <= logit_in;
                4'd8: v8 <= logit_in;
                4'd9: v9 <= logit_in;
            endcase
        end
    end

    // =========================================================
    // Capture argmax result and assert done
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            class_out <= 0;
            done      <= 1'b0;
        end else begin
            if (state == S_COMPUTE) begin
                class_out <= argmax_idx;
            end
            if (state == S_DONE)   done <= 1'b1;
            else                   done <= 1'b0;
        end
    end

endmodule
